export const entryPoints=[
 {id:'assessment',title:'Guide me from the beginning',copy:'Get to know yourself. Build your full plan.',symbol:'✳'},
 {id:'lifestyle',title:'Lifestyle Expectations',copy:'Picture your Austin life. Find the work that could support it.',symbol:'⌂'},
 {id:'college',title:'Career Paths With College',copy:'A field of study. A career. A route forward.',symbol:'◈'},
 {id:'training',title:'Career Paths Without College',copy:'Explore trades, apprenticeships, and practical training.',symbol:'↗'},
 {id:'careers',title:'Careers',copy:'Start broad. Find a specialty. Understand the work.',symbol:'◎'},
 {id:'income',title:'Income Expectations',copy:'Set an income goal. See possible routes to get there.',symbol:'$'}
];
export const careerFamilies=[
 {id:'creative',title:'Design & creativity',copy:'Make, design, write, and communicate.',paths:['design','visual-arts','media-language','culture','information-history'],symbol:'✎'},
 {id:'technology',title:'Technology & data',copy:'Build systems. Solve problems. Find patterns.',paths:['technology','secure-information','math-data'],symbol:'⌘'},
 {id:'health',title:'Health & helping',copy:'Support health and help people through everyday life.',paths:['health','nursing-care','rehabilitation','clinical-technology','medicines-nutrition','social-support'],symbol:'♡'},
 {id:'business',title:'Business & law',copy:'Organize, lead, analyze, and advocate.',paths:['business','accounting-finance','people-operations','law-policy'],symbol:'◇'},
 {id:'science',title:'Science & environment',copy:'Understand living systems and the world around us.',paths:['environment','living-systems','matter-earth','agriculture-outdoors'],symbol:'❋'},
 {id:'building',title:'Engineering & building',copy:'Design structures, machines, and places.',paths:['engineering','architecture-cities'],symbol:'△'},
 {id:'trades',title:'Trades & technical repair',copy:'Build, install, maintain, and repair.',paths:['skilled-trades'],symbol:'⚒'},
 {id:'services',title:'Food, hospitality & personal care',copy:'Make people welcome. Prepare food and provide personal services.',paths:['practical-care','hospitality-food','facilities-outdoor'],symbol:'☕'}
];
careerFamilies.push(...commonFamilies);
// Use actual catalog identifiers so the guided hierarchy covers every reviewed career.
const aliases={
 'visual-arts':'visual-arts','media-language':'media-communication','information-history':'information-history',
 'secure-information':'cybersecurity','math-data':'mathematics-data','nursing-care':'nursing','rehabilitation':'rehabilitation',
 'clinical-technology':'allied-health','medicines-nutrition':'medicine-nutrition','social-support':'social-support',
 'practical-care':'practical-service','accounting-finance':'accounting-finance','people-operations':'organizations-operations',
 'law-policy':'law-policy','living-systems':'life-sciences','matter-earth':'physical-sciences','architecture-cities':'architecture-cities'
};
const realPaths=new Set(directions.map(d=>d.id));
for(const f of careerFamilies)f.paths=f.paths.map(id=>realPaths.has(id)?id:aliases[id]).filter(id=>realPaths.has(id));
export const flowSteps=[['paths','Choose a path'],['career','Understand the work'],['education','Plan preparation'],['income','Explore income'],['life','Picture your life'],['next','Choose next steps'],['plan','My Plan']];
const ids=new Set(matchingOccupations.map(o=>o.id)),entries=new Set(entryPoints.map(x=>x.id));
const trailSets={familyIds:new Set(careerFamilies.map(f=>f.id)),pathIds:realPaths,taskInterests:new Set(Object.keys(taskPrompts)),likedActivityIds:new Set(curiosity.map(q=>q.id)),priorityIds:new Set(priorities.map(p=>p.id)),actionIds:new Set(['explore-sample','explore-notice','explore-next',...careerFamilies.map(f=>'explore-try-'+f.id)])};
const cleanTrail=raw=>raw&&typeof raw==='object'?Object.fromEntries(Object.entries(trailSets).map(([key,allowed])=>[key,[...new Set((Array.isArray(raw[key])?raw[key]:[]).filter(id=>allowed.has(id)))].slice(0,allowed.size)])):null;
export function rememberCareerFocus(state){const g=state.guide,id=g?.primaryCareer;if(!id)return;g.careerFocuses??={};if(g.careerFocuses[id])return;const paths=selectedPaths(g).filter(path=>pathCareerIds(path).includes(id)),fallback=occupationById(id)?.pathIds.filter(path=>realPaths.has(path))||[];const focusPaths=paths.length?selectedPaths(g):fallback.slice(0,3);g.careerFocuses[id]={pathIds:[...focusPaths],familyIds:paths.length?[...selectedFamilies(g)]:careerFamilies.filter(f=>f.paths.some(path=>focusPaths.includes(path))).map(f=>f.id).slice(0,3),taskInterests:paths.length?[...(g.taskInterests||[])]:[]};}
export function rememberExploration(state){const g=state.guide;if(!g||(g.planMode!=='exploration'&&!g.primaryCareer))return;rememberCareerFocus(state);const previous=cleanTrail(g.explorationTrail)||{},current={familyIds:selectedFamilies(g),pathIds:selectedPaths(g),taskInterests:g.taskInterests||[],likedActivityIds:curiosity.filter(q=>state.curiosity?.[q.id]>=4).map(q=>q.id),priorityIds:state.priorities||[],actionIds:[...state.actions.filter(a=>a.id.startsWith('explore-')).map(a=>a.id),...(g.planMode==='exploration'?explorationSteps(state).map(a=>a.id):[])]};g.explorationTrail=cleanTrail(Object.fromEntries(Object.keys(trailSets).map(key=>[key,[...(previous[key]||[]),...current[key]]])));}
export function explorationHistory(state){const trail=cleanTrail(state.guide?.explorationTrail);const actions=state.actions.filter(a=>a.id.startsWith('explore-')||trail?.actionIds.includes(a.id));return trail||actions.length?{...(trail||Object.fromEntries(Object.keys(trailSets).map(k=>[k,[]]))),actions}:null;}
export function exportPlanStep(a){return Object.fromEntries(['id','careerId','title','detail','dueDate','done','support','notice','learned','enjoyed','difficult','surprising','continueDecision'].filter(k=>a[k]!==undefined).map(k=>[k,a[k]]));}
export function freshGuide(){return {version:1,explorationTrail:null,careerFocuses:{},programChoices:{},planMode:'career',entry:'',step:'',family:'',familyIds:[],path:'',pathIds:[],candidate:'',careerBack:'guide/careers',careerIds:[],primaryCareer:'',salaryStage:'entry',salaryPicked:false,incomeTarget:'',lifestylePreset:'',lifestyleBuilder:freshLifestyleBuilder(),taskInterests:[],questionnaireVersion:'2.0.0',preparation:'',includeFinance:false,completed:false,lastRoute:''};}
export function cleanGuide(raw){const g=freshGuide();if(!raw||typeof raw!=='object')return g;g.planMode=raw.planMode==='exploration'?'exploration':'career';
 if(raw.programChoices&&typeof raw.programChoices==='object'&&!Array.isArray(raw.programChoices))for(const [career,program]of Object.entries(raw.programChoices))if(ids.has(career)&&typeof program==='string'&&/^[a-z0-9-]{1,100}$/.test(program))g.programChoices[career]=program;
 g.taskInterests=Array.isArray(raw.taskInterests)?[...new Set(raw.taskInterests.filter(x=>Object.hasOwn(taskPrompts,x)))].slice(0,12):[];
 if(entries.has(raw.entry))g.entry=raw.entry;if(['guide/paths','guide/specialty','guide/work-fit','guide/careers','career-tree'].includes(raw.careerBack))g.careerBack=raw.careerBack;
 for(const k of ['candidate','primaryCareer'])if(ids.has(raw[k]))g[k]=raw[k];
 if(careerFamilies.some(f=>f.id===raw.family))g.family=raw.family;
 if(realPaths.has(raw.path))g.path=raw.path;
 g.familyIds=Array.isArray(raw.familyIds)?[...new Set(raw.familyIds.filter(id=>careerFamilies.some(f=>f.id===id)))].slice(0,3):g.family?[g.family]:[];
 g.pathIds=Array.isArray(raw.pathIds)?[...new Set(raw.pathIds.filter(id=>realPaths.has(id)))].slice(0,3):g.path?[g.path]:[];
 g.family=g.familyIds[0]||'';g.path=g.pathIds[0]||'';
 g.careerIds=Array.isArray(raw.careerIds)?[...new Set(raw.careerIds.filter(id=>ids.has(id)))].slice(0,3):[];
 if(g.primaryCareer&&!g.careerIds.includes(g.primaryCareer))g.careerIds=[g.primaryCareer,...g.careerIds].slice(0,3);
 if(['entry','year5','year10','year20','custom',...(salaryProgression(g.primaryCareer)?.paidTraining?[salaryProgression(g.primaryCareer).paidTraining.stageKey]:[])].includes(raw.salaryStage))g.salaryStage=raw.salaryStage;
 if(typeof raw.incomeTarget==='string'&&raw.incomeTarget.trim()!==''&&Number.isFinite(Number(raw.incomeTarget))&&Number(raw.incomeTarget)>=1000&&Number(raw.incomeTarget)<=1000000)g.incomeTarget=String(Number(raw.incomeTarget));
 g.lifestyleBuilder=cleanLifestyleBuilder(raw.lifestyleBuilder);if(['shared','alone','comfort','custom'].includes(raw.lifestylePreset))g.lifestylePreset=raw.lifestylePreset;
 g.preparation=typeof raw.preparation==='string'?raw.preparation.slice(0,300):'';
 g.step=typeof raw.step==='string'?raw.step.slice(0,40):'';
 g.lastRoute=typeof raw.lastRoute==='string'&&/^(guide\/[a-z0-9/-]+|activity\/[a-z-]+|results|plan)$/.test(raw.lastRoute)?raw.lastRoute:'';
 if(raw.careerFocuses&&typeof raw.careerFocuses==='object')for(const [id,focus]of Object.entries(raw.careerFocuses)){if(!ids.has(id))continue;const c=cleanTrail(focus);if(c)g.careerFocuses[id]={familyIds:c.familyIds.slice(0,3),pathIds:c.pathIds.slice(0,3),taskInterests:c.taskInterests.slice(0,12)};}
 g.explorationTrail=cleanTrail(raw.explorationTrail);g.salaryPicked=raw.salaryPicked===true;g.includeFinance=raw.includeFinance===true;g.completed=raw.completed===true;return g;
}
export function startsAt(entry){return {assessment:'guide/assessment',lifestyle:'guide/lifestyle',income:'guide/income-goal',college:'guide/paths',training:'guide/paths',careers:'guide/paths'}[entry]||'overview';}
export function startGuide(state,entry){if(!entries.has(entry))return null;state.guide??=freshGuide();rememberExploration(state);state.guide.entry=entry;state.guide.planMode='career';if(entry==='lifestyle'){state.guide.lifestyleBuilder.step=0;state.guide.lifestyleBuilder.reviewing=false;}state.guide.completed=false;state.guide.salaryPicked=false;state.guide.family='';state.guide.familyIds=[];state.guide.path='';state.guide.pathIds=[];state.guide.candidate='';state.guide.taskInterests=[];state.guide.careerBack='guide/careers';state.guide.lastRoute=startsAt(entry);return startsAt(entry);}
export function isTraining(o){return o.finance?o.finance.routeType==='training'||o.finance.credentialLevel==='training':o.id==='psychiatric-aide'||o.id==='psychiatric-technician';}
export function routeCareers(state){const entry=state.guide?.entry;return occupations.filter(o=>entry==='training'?isTraining(o):entry==='college'?!isTraining(o):true);}
export function pathCareerIds(path){return occupations.filter(o=>o.pathIds.includes(path)||(path==='social-support'&&['psychiatric-aide','psychiatric-technician','clinical-psychologist'].includes(o.id))).map(o=>o.id);}
export function familyPaths(state,family){const f=careerFamilies.find(x=>x.id===family);if(!f)return [];const allowed=new Set(routeCareers(state).map(o=>o.id));return directions.filter(d=>f.paths.includes(d.id)&&pathCareerIds(d.id).some(id=>allowed.has(id)));}
export function availableFamilies(state){return careerFamilies.filter(f=>familyPaths(state,f.id).length).map((f,index)=>({...f,index,connection:fieldConnection(state,f.id)})).sort((a,b)=>state.guide?.entry==='assessment'?b.connection.score-a.connection.score||a.index-b.index:0);}
export function goalMatch(o,target){const p=salaryProgression(o.id);return p?.stages.find(s=>s.amount>=Number(target))||null;}
export function careerOptions(state){const g=state.guide||freshGuide(),paths=selectedPaths(g);let list=routeCareers(state).filter(o=>!paths.length||paths.some(path=>pathCareerIds(path).includes(o.id)));if(g.incomeTarget&&['income','lifestyle'].includes(g.entry))list=list.slice().sort((a,b)=>{const ma=goalMatch(a,g.incomeTarget),mb=goalMatch(b,g.incomeTarget);return (ma?ma.years:100)-(mb?mb.years:100);});if(g.taskInterests?.length)list=list.map((o,index)=>({o,index,match:careerConnection(state,o),choiceIndex:g.taskInterests.indexOf('work:'+o.id)})).sort((a,b)=>b.match.taskCount-a.match.taskCount||(a.choiceIndex<0?999:a.choiceIndex)-(b.choiceIndex<0?999:b.choiceIndex)||a.index-b.index).map(x=>x.o);return list;}
export function reflectionReasons(state,path){return [...new Set(careerFamilies.filter(f=>f.paths.includes(path)).flatMap(f=>fieldConnection(state,f.id).reasons))];}
export function suggestedPaths(state){const a=analyze(state);return [...new Set([...a.items.filter(d=>d.evidence.some(e=>['interest','experience','choice'].includes(e.source))).map(d=>d.id),...careerFamilies.filter(f=>fieldConnection(state,f.id).supported).flatMap(f=>f.paths)])];}

export function selectCareer(state,id,{alternative=false,restoreFocus=false}={}){if(!ids.has(id))return false;const g=state.guide??=freshGuide();
 if(alternative){if(g.careerIds.includes(id))return true;if(g.careerIds.length>=3)return false;g.careerIds.push(id);}
 else {rememberExploration(state);g.planMode='career';const changed=g.primaryCareer!==id;g.primaryCareer=id;g.candidate=id;g.careerIds=[id,...g.careerIds.filter(x=>x!==id)].slice(0,3);if(changed){g.preparation='';g.salaryStage=salaryProgression(id)?.paidTraining?.stageKey||'entry';g.salaryPicked=false;if(restoreFocus){rememberCareerFocus(state);const focus=g.careerFocuses[id];g.familyIds=[...focus.familyIds];g.family=g.familyIds[0]||'';g.pathIds=[...focus.pathIds];g.path=g.pathIds[0]||'';g.taskInterests=[...focus.taskInterests];}}}
 state.exploration??={};state.exploration.savedCareers??=[];if(!state.exploration.savedCareers.includes(id))state.exploration.savedCareers.push(id);return true;
}
export function applyGuidePay(state){const g=state.guide,p=state.finance.lifestyle;if(!g?.primaryCareer)return;const amount=salaryAtStage(g.primaryCareer,g.salaryStage);if(!Number.isFinite(amount))return;const changed=p.careerId!==g.primaryCareer||p.salaryStage!==g.salaryStage||Number(p.gross)!==amount;if(changed)Object.assign(p,salaryPreviewInputs(state,g.primaryCareer,g.salaryStage));else {p.careerId=g.primaryCareer;p.band='custom';p.gross=String(amount);p.salaryStage=g.salaryStage;}}
export function lifestylePreset(key){const p=freshLifestyle();const edits={shared:{rent:'818.50',utilities:'90',carMode:'transit',quickCount:'4',casualCount:'1',travel:'75',recreation:'75',clothing:'50'},alone:{rent:'1350',utilities:'180',carMode:'used'},comfort:{rent:'2100',utilities:'180',carMode:'new',carPrice:'32000',carDown:'5000',quickCount:'8',casualCount:'4',specialCount:'1',travel:'300',recreation:'200',clothing:'125'}};return {...p,...edits[key],housingMode:'rent'};}
export function requiredGross(p){const r=calculateLifestyle({...p,netMode:'manual',manualNet:'0'});if(r.status!=='illustration')return null;const health=Number(p.health)||0,percent=Number(p.retirement)||0;let lo=0,hi=1000000;for(let i=0;i<60;i++){const m=(lo+hi)/2,rate=Math.min(percent,24500/m*100);const net=employeeTaxes(m,rate).monthly-health;if(net<r.spending)lo=m;else hi=m;}return hi;}
export function applyLifestylePreset(state,key){if(!['shared','alone','comfort'].includes(key))return;const old=state.finance.lifestyle,p=lifestylePreset(key);for(const k of ['debt','extraNeeds','retirement','health','saving'])if(String(old[k]??'').trim()!==''&&Number.isFinite(Number(old[k]))&&Number(old[k])>=0)p[k]=old[k];state.finance.lifestyle=p;state.guide.lifestylePreset=key;const gross=requiredGross(p);state.guide.incomeTarget=gross===null?'':String(Math.ceil(gross));}
export function createExplorationPlan(state){state.guide.entry||='careers';state.guide.planMode='exploration';for(const step of explorationSteps(state)){if(!state.actions.some(a=>a.id===step.id)&&state.actions.length<80)state.actions.push({...step,dueDate:'',support:'',notice:'',done:false});}rememberExploration(state);state.guide.completed=true;state.guide.lastRoute='plan';}
export function activeExplorationActions(state){const steps=explorationSteps(state);return steps.map(step=>state.actions.find(a=>a.id===step.id)||{...step,done:false,dueDate:''});}
export function createPlanActions(state){const id=state.guide.primaryCareer,o=occupationById(id);if(!o)return;state.guide.careerFocuses??={};delete state.guide.careerFocuses[id];rememberCareerFocus(state);state.guide.planMode='career';const rows=careerPlanSteps(o,state).map(x=>[x.key,x.title,x.detail]);for(const [key,defaultTitle,defaultDetail]of rows){const [title,detail]=[defaultTitle,defaultDetail];const actionId=`guide-${id}-${key}`;if(!state.actions.some(a=>a.id===actionId)&&state.actions.length<80)state.actions.push({id:actionId,careerId:id,title,detail,dueDate:'',support:'',notice:'',done:false});}state.guide.completed=true;state.guide.lastRoute='plan';}
export function personalPlanExport(state){const g=cleanGuide(state.guide),exploring=g.planMode==='exploration',o=exploring?null:occupationById(g.primaryCareer);return {application:'Fieldguide',purpose:exploring?'Personal exploration plan; no career or financial projection assigned':'Personal exploration plan; salary milestones are planning estimates in today’s dollars',exportedAt:new Date().toISOString(),activityReflections:state.activityReflections||[],entryPoint:g.entry,planMode:g.planMode,...(state.profileJourney?.started?{guidedProfile:{version:state.profileJourney.version,questionOrder:state.profileJourney.questionOrder||[],matchingEngineVersion,earlierCustomInterestAnswers:{...state.curiosity,...state.profileJourney.interests},officialInterestAssessment:state.profileJourney.officialInterest,earlierAssessment:state.profileJourney.legacyAssessment,additionalInterestAnswers:state.profileJourney.interests||{},fieldWorkPreferences:state.profileJourney.fieldPreferences||{},visitedPathways:state.profileJourney.families,recommendedPathways:state.profileJourney.suggestedFamilies||[],skillExperience:state.profileJourney.skills,workPreferences:state.profileJourney.answers,expandedProfessionReflections:state.profileJourney.expandedInterests||{},pathwayQuestions:state.profileJourney.depth,aptitude:'Not measured by this questionnaire'}}:{}),...(exploring?{exploration:{status:explorationSnapshot(state),focuses:g.familyIds}}:{}),interests:{families:g.familyIds,paths:g.pathIds},primaryCareer:o?{id:o.id,title:o.title}:null,alternatives:(exploring?[]:g.careerIds).filter(id=>id!==g.primaryCareer).map(id=>({id,title:occupationById(id)?.title})),taskInterests:g.taskInterests.map(id=>({id,text:taskPrompts[id]})),questionnaireVersion:state.questionnaireVersion||'1.0.0',matchingVersion:state.profileJourney?.started?matchingEngineVersion:matchingVersion,programChoices:{...g.programChoices},selectedProgramId:o?g.programChoices[o.id]||null:null,preparation:exploring?'Explore classes, projects, and supervised experiences before choosing a career.':o?careerEducationSummary(o):'',preparationDetails:o?careerEducationBullets(o):[],studyFocus:g.preparation||null,salary:o?salaryProgression(o.id):null,salaryStage:exploring?null:g.salaryStage,selectedSalary:o&&!o.expandedDegree?{careerId:o.id,stage:g.salaryStage,annualGross:g.salaryStage==='custom'?Number(state.finance.lifestyle.gross):salaryAtStage(o.id,g.salaryStage),basis:salaryProgression(o.id)?.paidTraining?.stageKey===g.salaryStage?'Published paid-training example':salaryProgression(o.id)?.stages.find(s=>s.key===g.salaryStage)?.basis||'Personal income scenario'}:null,nextSteps:(exploring?activeExplorationActions(state):state.actions).map(exportPlanStep),...(explorationHistory(state)?{earlierExploration:{...explorationHistory(state),actions:explorationHistory(state).actions.map(exportPlanStep)}}:{}),...(!exploring&&g.includeFinance?{budgets:{careerScenarios:state.finance.careerScenarios,collegePlans:state.finance.plans,currentCareerCollegePlanIds:state.finance.plans.filter(p=>p.entityLinks.includes(o.id)).map(p=>p.id),lifestyle:{inputs:state.finance.lifestyle,result:calculateLifestyle(state.finance.lifestyle)}}}:{})};}

export const selectedFamilies=g=>g.familyIds?.length?g.familyIds:g.family?[g.family]:[];
export const selectedPaths=g=>g.pathIds?.length?g.pathIds:g.path?[g.path]:[];
export function specialtyOptions(state){const paths=new Set(selectedFamilies(state.guide).flatMap(id=>familyPaths(state,id).map(d=>d.id)));return directions.filter(d=>paths.has(d.id));}
export function toggleGuideFamily(state,id){const g=state.guide;if(!availableFamilies(state).some(f=>f.id===id))return false;rememberExploration(state);const picked=selectedFamilies(g);if(!picked.includes(id)&&picked.length>=3)return false;g.familyIds=picked.includes(id)?picked.filter(x=>x!==id):[...picked,id];g.family=g.familyIds[0]||'';const allowed=new Set(specialtyOptions(state).map(d=>d.id));g.pathIds=selectedPaths(g).filter(x=>allowed.has(x));g.path=g.pathIds[0]||'';g.taskInterests=selectedPaths(g).length?g.taskInterests.filter(t=>!t.startsWith('work:')||careerOptions(state).some(o=>t==='work:'+o.id)):[];g.candidate='';return true;}
export function toggleGuidePath(state,id){const g=state.guide;if(!specialtyOptions(state).some(d=>d.id===id))return false;rememberExploration(state);const picked=selectedPaths(g);if(!picked.includes(id)&&picked.length>=3)return false;g.pathIds=picked.includes(id)?picked.filter(x=>x!==id):[...picked,id];g.path=g.pathIds[0]||'';g.taskInterests=selectedPaths(g).length?g.taskInterests.filter(t=>!t.startsWith('work:')||careerOptions(state).some(o=>t==='work:'+o.id)):[];g.candidate='';return true;}
export function salaryPreviewInputs(state,id,stage,{amount:override}={}){const amount=Number.isFinite(override)?override:salaryAtStage(id,stage);if(!Number.isFinite(amount))return null;const scenario=state.finance.careerScenarios?.[id]||freshCareerScenario(),old=state.finance.lifestyle,loan=scenario?.debtLinked?fundingScenario(scenario):null,linkedPayment=loan?.status==='scenario'?loan.paymentWithStudyInterest:0;const p={...old,...(scenario?{weeklyHours:scenario.weeklyHours,paidWeeks:scenario.paidWeeks,workMode:scenario.workMode,businessExpenses:scenario.businessExpenses}:{}),debt:String(Math.max(0,Number(old.debt)-Number(old.linkedLoanPayment||0))+linkedPayment),linkedLoanPayment:String(linkedPayment),careerId:id,band:'custom',gross:String(amount),netMode:'estimate',salaryStage:stage};p.retirement=String(Math.min(Number(p.retirement)||0,100,Math.floor(24500/amount*100*1e8)/1e8));return p;}

export function advanceInterests(state){const options=specialtyOptions(state);if(!options.length)return 'guide/paths';const allowed=new Set(routeCareers(state).map(o=>o.id)),possible=[...new Set(options.flatMap(d=>pathCareerIds(d.id)).filter(id=>allowed.has(id)))];if(possible.length===1){state.guide.pathIds=[options[0].id];state.guide.path=options[0].id;state.guide.candidate=possible[0];state.guide.careerBack='guide/paths';return 'guide/career/'+possible[0];}if(options.length===1){state.guide.pathIds=[options[0].id];state.guide.path=options[0].id;return 'guide/work-fit';}return 'guide/specialty';}
export function advanceSpecialties(state){const options=careerOptions(state);if(!selectedPaths(state.guide).length)return 'guide/specialty';if(options.length===1){state.guide.candidate=options[0].id;state.guide.careerBack='guide/specialty';return 'guide/career/'+options[0].id;}return 'guide/work-fit';}

// Older saved drafts keep their history and resume at the shared career-field step.
export function resolvePlanRoute(state,route){return route==='plan'&&state.guide?.planMode==='exploration'?'guide/paths':route;}
